import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AfterEffectsBounceProps = Record<string, any>;

const AfterEffectsBounce: React.FC<AfterEffectsBounceProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 4,
  logoImage = "https://upload.wikimedia.org/wikipedia/commons/c/cb/Adobe_After_Effects_CC_icon.svg",
  logoSize = 400,
  spinRotations = 3,
  extrusionDepth = 30, // Adds 3D thickness by layering the image
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  // Logic to prevent parser errors on transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. Launch Spring
  // Configured for a fast throw, natural elastic overshoot, and crisp settle
  const launchProgress = spring({
    frame,
    fps,
    config: {
      stiffness: 150, // High stiffness for a fast upward launch
      damping: 12,    // Tuned damping to allow a slight overshoot
      mass: 0.7,      // Lighter mass ensures a snappy return and elastic bounce
    },
  });

  // 2. Drop Timing & Logic
  const dropDuration = Math.round(fps * 1.5); // 1.5 seconds for the gravity drop
  
  // Ensure we hold for at least a beat (1.5s launch/hold) before dropping, 
  // snapping the drop exactly to the end of the composition's duration.
  const dropStartFrame = Math.max(
    Math.round(fps * 1.5), 
    durationInFrames - dropDuration
  );

  // Gravity interpolation
  const dropProgress = interpolate(
    frame,
    [dropStartFrame, dropStartFrame + dropDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      // Easing.quad mathematically mimics natural gravity (constant acceleration / t^2)
      easing: Easing.quad, 
    }
  );

  // 3. Position Calculations
  const startY = height * 1.2; // Start securely off the bottom of the screen
  const centerY = height * 0.5; // Target resting position (exact center)

  // Map the spring curve to physical Y coordinates
  const springY = interpolate(launchProgress, [0, 1], [startY, centerY], {
    extrapolateLeft: "extend",
    extrapolateRight: "extend", // Allow the spring's >1.0 overshoot to translate to physical pixels
  });

  // 4. 3D Spin Calculations
  const spinDegrees = spinRotations * 360;
  
  // Primary horizontal tumble (Y-axis)
  const rotationY = interpolate(launchProgress, [0, 1], [spinDegrees, 0], {
    extrapolateLeft: "extend",
    extrapolateRight: "extend", // The elasticity of the spring will make it physically wobble into place!
  });

  // Secondary vertical tilt (X-axis) for extra 3D depth
  const rotationX = interpolate(launchProgress, [0, 1], [spinDegrees * 0.5, 0], {
    extrapolateLeft: "extend",
    extrapolateRight: "extend",
  });

  // Calculate the total distance required to fall completely off-screen
  const dropDistance = height * 0.5 + logoSize + 100;

  // Add the accelerating drop displacement to the settled spring position
  const currentY = springY + (dropProgress * dropDistance);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
        overflow: "hidden",
        perspective: 1200, // Establishes the 3D viewing space
      }}
    >
      <div
        style={{
          width: logoSize,
          height: logoSize,
          // Subtracting (height / 2) because the flex container inherently centers the item.
          // Applying translateY first, followed by our 3D rotations so it rotates on its own center.
          transform: `translateY(${currentY - height / 2}px) rotateY(${rotationY}deg) rotateX(${rotationX}deg)`,
          transformStyle: "preserve-3d", // Maintains full 3D rendering context for the extruded stack
          transition: "none",
        }}
      >
        {/* Render a stack of images pushed back along the Z-axis to create solid 3D extrusion */}
        {Array.from({ length: extrusionDepth }).map((_, index) => {
          const isFront = index === 0;
          const isBack = index === extrusionDepth - 1;
          const isEdge = !isFront && !isBack;
          
          // Offset the layers so the 3D rotation pivot is perfectly centered in the block
          const zPos = (extrusionDepth / 2) - index;

          return (
            <img
              key={index}
              src={logoImage}
              alt={isFront ? "Logo" : ""}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
                transform: `translateZ(${zPos}px)`,
                // Darken the inner layers to simulate shading, keeping front/back bright and applying drop-shadow to the back
                filter: isEdge 
                  ? "brightness(0.35)" 
                  : isBack 
                    ? "drop-shadow(0px 20px 40px rgba(0,0,0,0.5))" 
                    : "none",
                transition: "none",
                backfaceVisibility: "visible",
              }}
            />
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default AfterEffectsBounce;